import{_ as r,o as a,c as s,a2 as n}from"./chunks/framework.DdtnLau3.js";const k=JSON.parse('{"title":"Harness","description":"","frontmatter":{},"headers":[],"relativePath":"zh/concepts/harness.md","filePath":"zh/concepts/harness.md"}'),o={name:"zh/concepts/harness.md"};function t(i,e,l,p,c,h){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h1><p><strong>Harness 是 Work 的智能层</strong>。它将模型执行、工具、工作空间上下文、对话和任务验证，连接到 Work 实际运行的环境。</p><p>每个 Work 都有自己的 Harness。聊天是它的一个入口；它还使用文件、Work 专属 Service 工具、Skills 和 Pi Packages，理解并操作整个工作空间。</p><h2 id="当前能做什么" tabindex="-1">当前能做什么 <a class="header-anchor" href="#当前能做什么" aria-label="Permalink to &quot;当前能做什么&quot;">​</a></h2><p>Piwork 在 Work 的 Agent 容器内运行基于 <strong>Pi Agent SDK</strong> 的 TypeScript Harness。它管理 Sessions 和 Runs，加载指令和工具，调用已配置的模型，并保存私有对话历史。</p><p>通过这些工具，它可以：</p><ul><li>检查工作空间文件和可用 Services。</li><li>执行任务并操作应用数据。</li><li>构建或修改工作空间中的应用源码。</li><li>通过 Core 声明、操作和检查 Services。</li><li>使用 Work 专属指令、Skills 和扩展包。</li></ul><p>例如，在 Kanban Work 中，可以让它检查看板存储、增加功能、重启相关 Service，再验证应用仍能使用。模型说“完成”不等于变更已经通过验证。</p><h2 id="为什么是-可演进的" tabindex="-1">为什么是“可演进的”？ <a class="header-anchor" href="#为什么是-可演进的" aria-label="Permalink to &quot;为什么是“可演进的”？&quot;">​</a></h2><p>Harness 的上下文属于 Work。随着工作空间发展，它的指令、Skills、工具和扩展包可以更适合这个环境。这些资源和历史会随 Work 一起导出。</p><p>当前<strong>实验性 <code>piwork-brain</code> 包</strong>提供结构化 Service 交互、任务证据、经过验证的经验，以及准备扩展包自身变更的受控路径。候选经验只有在关联任务成功验证后才生效。准备好的扩展包变更，需要用户显式 <strong>Apply</strong> 并执行行为检查；修改文件不会热更新正在运行的 Harness。</p><p>因此，演进有具体含义：调整操作某个工作空间所需的资源，同时保留可检查的配置、运行上下文和验证结果。</p><h2 id="长期方向" tabindex="-1">长期方向 <a class="header-anchor" href="#长期方向" aria-label="Permalink to &quot;长期方向&quot;">​</a></h2><p>目标是让 Harness 越来越适合特定 Work 和用户。这是产品方向，不是对无限制自动自我改进的承诺。当前行为取决于启用的扩展包、兼容镜像、可用工具和模型配置。</p><p>Harness 不能绕过 Core 的权限、配额和生命周期规则。导出持久上下文不会导出模型 API Key，也不会让接收方恢复正在执行的任务。</p><p>当前接口和实验性边界见 <a href="/piwork/zh/spec/harness.html">Harness 规范</a>。</p>',16)])])}const _=r(o,[["render",t]]);export{k as __pageData,_ as default};
